use xiom.io;

enum Pet {
  Dog(breed: Str),
  Cat(color: Str),
  Fish(tank_size: Int),
  Bird(can_talk: Bool),
}

fn describe(p: Pet) -> Str {
  match p {
    Dog(breed) => { return "A " + breed + " dog"; }
    Cat(color) => { return "A " + color + " cat"; }
    Fish(tank_size) => { return "A fish needing " + tank_size + "L tank"; }
    Bird(can_talk) => {
      if can_talk { return "A talking bird"; }
      return "A quiet bird";
    }
  }
}

fn needs_cage(p: Pet) -> Bool {
  match p {
    Bird(_) => { return true; }
    _ => { return false; }
  }
}

fn main() -> Int {
  let p1 = Pet.Dog("Beagle");
  let p2 = Pet.Cat("Black");
  let p3 = Pet.Fish(30);
  let p4 = Pet.Bird(false);
  var total = 0;
  match p1 { Fish(size) => { total = total + size; } _ => {} }
  match p2 { Fish(size) => { total = total + size; } _ => {} }
  match p3 { Fish(size) => { total = total + size; } _ => {} }
  match p4 { Fish(size) => { total = total + size; } _ => {} }
  return total;
}
